import{_ as r,a8 as a,o as s,c as d,ah as i,K as n}from"./chunks/framework.BPpifGc1.js";import"./chunks/theme.e9TzJunN.js";const f=JSON.parse('{"title":"Agent 记忆系统详细规范","description":"","frontmatter":{},"headers":[],"relativePath":"vault/_Skills/agent-memory/references/constitution.md","filePath":"vault/_Skills/agent-memory/references/constitution.md","lastUpdated":1784383933000}'),l={name:"vault/_Skills/agent-memory/references/constitution.md"};function c(h,t,g,p,m,b){const e=a("NolebaseGitContributors"),o=a("NolebaseGitChangelog");return s(),d("div",null,[t[0]||(t[0]=i(`<h1 id="agent-记忆系统详细规范" tabindex="-1">Agent 记忆系统详细规范 <a class="header-anchor" href="#agent-记忆系统详细规范" aria-label="Permalink to “Agent 记忆系统详细规范”">​</a></h1><blockquote><p>本文档是模板文件的详细设计说明书，解释每个字段和规则的意图。</p></blockquote><h2 id="设计哲学" tabindex="-1">设计哲学 <a class="header-anchor" href="#设计哲学" aria-label="Permalink to “设计哲学”">​</a></h2><h3 id="为什么不保存完整聊天历史" tabindex="-1">为什么不保存完整聊天历史 <a class="header-anchor" href="#为什么不保存完整聊天历史" aria-label="Permalink to “为什么不保存完整聊天历史”">​</a></h3><p>聊天历史会腐烂。三个月前的对话细节今天看毫无意义。但从中提炼出的<strong>决策、约定、偏好</strong>可以保鲜数年。</p><p><strong>记忆系统的目标</strong>：把 AI 编码助手的上下文序列化为简洁、具体、可检索的 Markdown 文件，在不同 Agent、不同会话之间保持连续性。</p><h3 id="跨-ai-工具兼容性" tabindex="-1">跨 AI 工具兼容性 <a class="header-anchor" href="#跨-ai-工具兼容性" aria-label="Permalink to “跨 AI 工具兼容性”">​</a></h3><p>本规范设计为<strong>框架无关</strong>：</p><ul><li>WorkBuddy / Cursor / Codex / Claude Code / Copilot — 任何 AI 编码工具都能读写</li><li>所有文件都是纯 Markdown，不依赖任何特定工具的 API</li><li>唯一依赖：文件系统读写权限</li></ul><p><strong>关键前提</strong>：AI 工具不会自动读取 <code>.memory/</code>。必须通过工具配置文件引用（详见 SKILL.md &gt; 工具适配指南）。</p><hr><h2 id="目录结构详解" tabindex="-1">目录结构详解 <a class="header-anchor" href="#目录结构详解" aria-label="Permalink to “目录结构详解”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light one-dark-pro" style="--shiki-light:#24292e;--shiki-dark:#abb2bf;--shiki-light-bg:#fff;--shiki-dark-bg:#282c34;" tabindex="0" dir="ltr"><code><span class="line"><span>.memory/                          # 项目根目录下的隐藏目录</span></span>
<span class="line"><span>├── AGENTS.md                     # 唯一入口 — AI 会话的必读文件，含项目身份 + 工作流指令</span></span>
<span class="line"><span>├── context/                      # 上下文记录</span></span>
<span class="line"><span>│   └── decisions.md              # 技术决策日志（按日期追加，带分类标签）</span></span>
<span class="line"><span>├── working/                      # 进行中的工作</span></span>
<span class="line"><span>│   ├── todo.md                   # 进度跟踪</span></span>
<span class="line"><span>│   └── plan.md                   # 当期实施计划（可选）</span></span>
<span class="line"><span>└── archive/                      # 历史存档</span></span>
<span class="line"><span>    ├── decisions-YYYY-QX.md      # 按季度归档的旧决策</span></span>
<span class="line"><span>    └── plan-{阶段名}.md          # 已完成阶段的计划</span></span></code></pre></div><h3 id="agents-md" tabindex="-1">AGENTS.md <a class="header-anchor" href="#agents-md" aria-label="Permalink to “AGENTS.md”">​</a></h3><p><strong>用途</strong>：AI Agent 的「项目入职文档」，也是<strong>唯一入口</strong>。每次新会话的必读文件。</p><p><strong>自包含性</strong>：AGENTS.md 不仅含项目身份和约定，还内置了完整的会话工作流（启动时读什么、收尾时写什么、决策记录格式）。AI 读这一个文件即拥有全部操作知识，<strong>无需复制粘贴任何额外指令</strong>。</p><p><strong>设计决策</strong>：</p><ul><li>初始化为<strong>骨架</strong>而非<strong>占位模板</strong>：不加 <code>[待填写]</code>，用斜体引导提示，AI 和人在开发中增量填充</li><li>这是刻意设计——新项目在开始写代码之前，不知道技术栈和约定是什么</li><li>第一版只包含项目名称和记忆文件索引；其余在开发中长出来</li></ul><p><strong>不是</strong>：README.md（给人看的）、CONTRIBUTING.md（贡献指南）。AGENTS.md 是写给 AI 的。</p><h3 id="context-decisions-md" tabindex="-1">context/decisions.md <a class="header-anchor" href="#context-decisions-md" aria-label="Permalink to “context/decisions.md”">​</a></h3><p><strong>用途</strong>：技术决策的记录与追责。</p><p><strong>格式</strong>：<code>[YYYY-MM-DD] [分类] 决策项 → 选定方案 | 原因 | via:来源</code></p><p><strong>分类标签</strong>：</p><ul><li><code>[架构]</code> — 系统架构、模块划分、数据流</li><li><code>[工具]</code> — 依赖/库/第三方服务选型</li><li><code>[约定]</code> — 代码规范、命名、流程</li><li><code>[性能]</code> — 性能优化策略</li><li><code>[安全]</code> — 安全策略与措施</li></ul><p><strong>维护</strong>：每季度归档超过 90 天的已固化决策至 <code>archive/decisions-YYYY-QX.md</code>。</p><h3 id="working-todo-md" tabindex="-1">working/todo.md <a class="header-anchor" href="#working-todo-md" aria-label="Permalink to “working/todo.md”">​</a></h3><p><strong>用途</strong>：开发进度跟踪。每次会话结束时更新。</p><p><strong>格式</strong>：进度表（阶段 | 状态 | 完成时间）+ 当前位置描述 + 待办复选框。</p><p><strong>维护</strong>：每个阶段结束后清理已完成条目。</p><h3 id="working-plan-md-可选" tabindex="-1">working/plan.md（可选） <a class="header-anchor" href="#working-plan-md-可选" aria-label="Permalink to “working/plan.md（可选）”">​</a></h3><p><strong>用途</strong>：当前阶段的详细实施计划。任务需要 3+ 步骤时创建，完成后移至 <code>archive/</code>。</p><hr><h2 id="操作规范" tabindex="-1">操作规范 <a class="header-anchor" href="#操作规范" aria-label="Permalink to “操作规范”">​</a></h2><h3 id="写入时机" tabindex="-1">写入时机 <a class="header-anchor" href="#写入时机" aria-label="Permalink to “写入时机”">​</a></h3><table tabindex="0"><thead><tr><th>信息类型</th><th>写入目标</th><th>示例</th></tr></thead><tbody><tr><td>技术决策</td><td><code>context/decisions.md</code></td><td>「放弃 Redis 改用内存缓存，因为数据量 &lt; 100MB」</td></tr><tr><td>项目约定</td><td><code>AGENTS.md</code></td><td>「所有函数必须写类型注解」</td></tr><tr><td>进度更新</td><td><code>working/todo.md</code></td><td>「阶段二已完成，进入阶段三」</td></tr><tr><td>实施方案</td><td><code>working/plan.md</code></td><td>任务需要 3+ 步骤时创建</td></tr></tbody></table><h3 id="读取策略-分层-避免浪费-token" tabindex="-1">读取策略（分层，避免浪费 token） <a class="header-anchor" href="#读取策略-分层-避免浪费-token" aria-label="Permalink to “读取策略（分层，避免浪费 token）”">​</a></h3><table tabindex="0"><thead><tr><th>层级</th><th>文件</th><th>触发条件</th></tr></thead><tbody><tr><td>必须读</td><td><code>AGENTS.md</code></td><td>所有任务</td></tr><tr><td>继续开发时读</td><td><code>working/todo.md</code>、<code>working/plan.md</code></td><td>继续昨天的工作</td></tr><tr><td>牵涉架构时查</td><td><code>context/decisions.md</code></td><td>做技术选型、修改核心模块、重构时<strong>搜索</strong>而非全文加载</td></tr></tbody></table><h3 id="写入原则" tabindex="-1">写入原则 <a class="header-anchor" href="#写入原则" aria-label="Permalink to “写入原则”">​</a></h3><ol><li><strong>简洁具体</strong> — 不复制代码或对话，只记录要点和结论</li><li><strong>可检索</strong> — 使用清晰的标题、关键词和分类标签</li><li><strong>可对比</strong> — 重要决策记录备选方案和理由</li><li><strong>有时效</strong> — 标注日期，过时信息及时更新或归档</li><li><strong>不含敏感信息</strong> — 不存储密钥、凭证等</li><li><strong>标记来源</strong> — 使用 <code>via:来源</code> 标记写入者</li></ol><hr><h2 id="并发与冲突处理" tabindex="-1">并发与冲突处理 <a class="header-anchor" href="#并发与冲突处理" aria-label="Permalink to “并发与冲突处理”">​</a></h2><ul><li>支持多个 Agent 顺序使用，但<strong>不建议同时写入同一文件</strong></li><li>若可能发生并发写入：各 Agent 写入独立的临时文件，人工合并</li><li>写入前若发现文件已被其他 Agent 修改，提示用户处理</li></ul><hr><h2 id="架构选择-项目级独立记忆" tabindex="-1">架构选择：项目级独立记忆 <a class="header-anchor" href="#架构选择-项目级独立记忆" aria-label="Permalink to “架构选择：项目级独立记忆”">​</a></h2><p>本系统刻意设计为<strong>纯项目级</strong>，不依赖全局记忆层：</p><ul><li><strong>.memory/</strong> 是自包含的：每个项目的记忆目录完整独立，不引用外部文件</li><li><strong>专注性</strong>：日常开发通常只专注 1-2 个项目，全局记忆层增加维护负担而收益有限</li><li><strong>可迁移性</strong>：整个项目目录（含 .memory/）可以直接拷贝、打包、归档，不丢失上下文</li><li><strong>简化心智模型</strong>：不需要在「全局记什么、项目记什么」之间做选择</li></ul><hr><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to “参考”">​</a></h2><ul><li><code>maintenance.md</code> — 定期维护操作手册，包含存档策略和清理流程</li></ul>`,49)),n(e),n(o)])}const x=r(l,[["render",c]]);export{f as __pageData,x as default};
